using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Demo6.Game;using Newtonsoft.Json.Linq;
public static class V9Import {
 const string Source="E:/personalProject/Demo3/demo6/아트/정수리-시안적용-v9";
 public static object Run(){if(!Application.dataPath.Contains("topdown-v9-review-isolated")||EditorApplication.isPlaying)throw new Exception("Owned isolated Edit only");var set=AssetDatabase.LoadAssetAtPath<CombatArtSet>("Assets/Data/Combat/CombatArtSet.asset");if(EditorUtility.IsDirty(set))throw new Exception("Unsaved art set preserved");var rows=new List<object>();foreach(var p in JArray.Parse(File.ReadAllText(Source+"/runtime-manifest.json"))){string id=(string)p["id"];bool hero=(int)p["ppu"]==256;string dir=hero?"Assets/Art/TopDownPilotV9/Hero":"Assets/Resources/TopDownPilotV9";Directory.CreateDirectory(dir);string file=dir+"/"+id+".png";File.Copy(Source+"/runtime-PNG/"+id+".png",file,true);AssetDatabase.ImportAsset(file,ImportAssetOptions.ForceSynchronousImport);var imp=(TextureImporter)AssetImporter.GetAtPath(file);imp.textureType=TextureImporterType.Sprite;imp.spriteImportMode=SpriteImportMode.Single;imp.spritePixelsPerUnit=(float)p["ppu"];imp.isReadable=false;imp.mipmapEnabled=true;imp.filterMode=FilterMode.Trilinear;imp.wrapMode=TextureWrapMode.Clamp;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.sRGBTexture=true;imp.alphaIsTransparency=true;imp.maxTextureSize=4096;var st=new TextureImporterSettings();imp.ReadTextureSettings(st);st.spriteMeshType=SpriteMeshType.FullRect;st.spriteAlignment=(int)SpriteAlignment.Custom;st.spritePivot=new Vector2((float)p["pivot"][0],(float)p["pivot"][1]);imp.SetTextureSettings(st);imp.SaveAndReimport();var sp=AssetDatabase.LoadAssetAtPath<Sprite>(file);rows.Add(new{id,path=file,width=sp.rect.width,height=sp.rect.height,ppu=sp.pixelsPerUnit,pivot=sp.pivot.ToString(),mipmap=imp.mipmapEnabled,compression=imp.textureCompression.ToString()});}
 Sprite S(string id)=>AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Art/TopDownPilotV9/Hero/"+id+".png");var a=set.topDown.player;a.body=S("body_leather");a.sleeve=S("sleeve_leather");a.boot=S("boot_leather");a.fist=S("fist_leather_closed");a.cape=S("short_cape");foreach(var v in a.armors)if(v.armorId=="arm_leather"){v.body=a.body;v.sleeve=a.sleeve;}foreach(var v in a.helms)if(v.helmId=="hlm_leather")v.sprite=S("helm_leather");foreach(var v in a.gloves)if(v.glovesId=="glv_leather"){v.fistClosed=S("fist_leather_closed");v.fistOpen=S("fist_leather_open");}foreach(var v in a.boots)if(v.bootsId=="bts_leather")v.boot=a.boot;set.topDown.weapons.longsword=S("longsword");EditorUtility.SetDirty(set);AssetDatabase.SaveAssetIfDirty(set);File.WriteAllText(Source+"/import-validation.json",Newtonsoft.Json.JsonConvert.SerializeObject(rows,Newtonsoft.Json.Formatting.Indented));return rows;}
}
